def sort_on_occurence(lst):
    """Write a function to sort the given list based on the occurrence of first element of tuples.

    Groups tuples by their first element, preserving the order in which
    each key first appears and the order of the remaining elements within
    each group. Each group becomes ``(key, *values, count)`` and the
    groups are sorted by ``count`` in descending order; groups with equal
    counts keep their first-appearance order (stable sort).
    """
    grouped = {}
    counts = {}
    for item in lst:
        key = item[0]
        if key not in grouped:
            grouped[key] = []
            counts[key] = 0
        grouped[key].extend(item[1:])
        counts[key] += 1
    result = [(key, *values, counts[key]) for key, values in grouped.items()]
    result.sort(key=lambda group: group[-1], reverse=True)
    return result
